// HTMX 最小占位（生产环境应使用 htmx.min.js 完整版）
// 此文件仅保证开发环境不报 404，实际 HTMX 功能需替换为官方 htmx.min.js
window.htmx = window.htmx || {
    config: {},
    on: function(){}, off: function(){}, trigger: function(){},
    ajax: function(){}, process: function(){}, closest: function(){ return null; }
};
document.addEventListener('DOMContentLoaded', function() {
    // 简易 hx-get 加载器（开发占位）
    document.querySelectorAll('[hx-get]').forEach(function(el) {
        var target = el.getAttribute('hx-target') ? document.querySelector(el.getAttribute('hx-target')) : el;
        var url = el.getAttribute('hx-get');
        var headers = {};
        if (window.__ACCESS_TOKEN__) headers['Authorization'] = 'Bearer ' + window.__ACCESS_TOKEN__;
        fetch(url, {headers: headers, credentials: 'include'})
            .then(function(r){ return r.text(); })
            .then(function(html){ if (target) target.innerHTML = html; })
            .catch(function(){});
    });
});
